let modifiedLine = line;
// Replace inline-style links or reference-style links e.g:
// This is [Document 1](doc1.md)
// [doc1]: doc1.md
const linkTitlePattern = '(?:\\s+(?:\'.*?\'|".*?"|\\(.*?\\)))?';
// The query/hash suffix of the link URL. We don't want it to interfere
// with the detection of the .mdx? extension, so it's kept separate.
const linkSuffixPattern = '(?:\\?[^#>\\s]+)?(?:#[^>\\s]+)?';
const linkCapture = (forbidden: string) =>
  `((?!https?://|@site/)[^${forbidden}#?]+)`;
const linkURLPattern = `(?:${linkCapture(
  '()\\s',
)}${linkSuffixPattern}|<${linkCapture('>')}${linkSuffixPattern}>)`;
const linkPattern = new RegExp(
  `\\[(?:(?!\\]\\().)*\\]\\(\\s*${linkURLPattern}${linkTitlePattern}\\s*\\)|^\\s*\\[[^\\[\\]\\s]+\\]:\\s*${linkURLPattern}${linkTitlePattern}\\s*$`,
  'dgm',
);
let mdMatch = linkPattern.exec(modifiedLine);
while (mdMatch !== null) {
  // Capture group 1 is the bare URL, group 2 the <wrapped> URL
  const mdLink = (mdMatch[1] ?? mdMatch[2])!;

  if (/\.mdx?$/.test(mdLink)) {
    const sourcesToTry: string[] = [];
    // ./file.md and ../file.md are always relative to the current file
    if (!mdLink.startsWith('./') && !mdLink.startsWith('../')) {
      sourcesToTry.push(contentPathLocalized, contentPath, siteDir);
    }
    // /file.md is always relative to the content path
    if (!mdLink.startsWith('/')) {
      sourcesToTry.push(path.dirname(filePath));
    }

    const aliasedSourceMatch = sourcesToTry
      .map((p) => path.join(p, decodeURIComponent(mdLink)))
      .map((source) => {
        const relativePath = posixPath(path.relative(siteDir, source));
        return `${siteAliasPrefix}/${relativePath}`;
      })
      .find((source) => sourceToPermalink[source]);

    const permalink: string | undefined = aliasedSourceMatch
      ? sourceToPermalink[aliasedSourceMatch]
      : undefined;

    if (permalink) {
      // MDX won't be happy if the permalink contains a space, we need to
      // convert it to %20
      const encodedPermalink = permalink
        .split('/')
        .map((part) => part.replace(/\s/g, '%20'))
        .join('/');
      const [filenameStart, filenameEnd] = (mdMatch.indices?.[1] ??
        mdMatch.indices?.[2])!;
      // Only replace the file name part, keeping the query/hash and the
      // link title intact
      modifiedLine =
        modifiedLine.slice(0, filenameStart) +
        encodedPermalink +
        modifiedLine.slice(filenameEnd);
