let lastCodeFence: string | null = null;
const lines = fileString.split('\n').map((line) => {
  const codeFence = line.trimStart().match(/^`{3,}|^~{3,}/)?.[0];
  if (codeFence) {
    if (!lastCodeFence) {
      lastCodeFence = codeFence;
      // If we are in a ````-fenced block, all ``` would be plain text instead
      // of fences
    } else if (codeFence.startsWith(lastCodeFence)) {
      lastCodeFence = null;
    }
  }
  if (lastCodeFence) {
    return line;
  }

  let modifiedLine = line;
  // Replace inline-style links or reference-style links e.g:
  // This is [Document 1](doc1.md)
  // [doc1]: doc1.md
  const linkTitlePattern = '(?:\\s+(?:\'.*?\'|".*?"|\\(.*?\\)))?';
  // The query/hash suffix of the link URL. We don't want it to interfere
  // with the detection of the .mdx? extension, so it's kept separate.
  const linkSuffixPattern = '(?:\\?[^#>\\s]+)?(?:#[^>\\s]+)?';
  const linkCapture = (forbidden: string) =>
    `((?!https?://|@site/)[^${forbidden}#?]+)`;
  const linkURLPattern = `(?:${linkCapture(
    '()\\s',
  )}${linkSuffixPattern}|<${linkCapture('>')}${linkSuffixPattern}>)`;
  const linkPattern = new RegExp(
    `\\[(?:(?!\\]\\().)*\\]\\(\\s*${linkURLPattern}${linkTitlePattern}\\s*\\)|^\\s*\\[[^\\[\\]\\s]+\\]:\\s*${linkURLPattern}${linkTitlePattern}\\s*$`,
    'dgm',
  );
  let mdMatch = linkPattern.exec(modifiedLine);
  while (mdMatch !== null) {
    // The URL is captured either by the bare form (groups 1 & 3) or the
    // <wrapped> form (groups 2 & 4), depending on which alternative matched
    const urlMatchIndex = [1, 2, 3, 4].find((i) => mdMatch![i] !== undefined)!;
    const mdLink = mdMatch[urlMatchIndex]!;

